func sampleUnknown(d audit.DriftReport, limit int) []string {
  var all []string
  all = append(all, d.UnknownPaths...)
  all = append(all, d.UnknownAPIs...)
  all = append(all, d.UnknownSymbols...)
  if len(all) > limit {
    all = all[:limit]
  }
  return all
}

